import React, { useContext } from 'react';
import { Container, Row, Col, Button, Navbar, Badge } from 'react-bootstrap';
import { NavLink } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import AdminRoutes from './AdminRoutes';
import { FaUsers, FaChartBar, FaListAlt, FaCog, FaPlusCircle } from 'react-icons/fa';

const AdminDashboard = () => {
  const { logout, user } = useContext(AuthContext);

  const toggleTheme = () => {
    const cur = document.documentElement.getAttribute('data-theme');
    const next = cur === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
  };

  return (
    <div className="min-vh-100 d-flex flex-column">
      {/* Top Navbar */}
      <Navbar expand="lg" className="px-4 py-3 bg-body border-bottom shadow-sm">
        <Navbar.Brand className="d-flex align-items-center gap-2 fw-bold fs-4 text-primary">
          <div 
            className="d-flex align-items-center justify-content-center"
            style={{
              width: '38px',
              height: '38px',
              borderRadius: '12px',
              background: 'var(--primary-gradient)',
              color: '#fff',
              fontSize: '18px'
            }}
          >
            ⚡
          </div>
          Nexus CRM <Badge bg="primary" className="ms-1 fs-6" style={{ fontSize: '11px' }}>Central Admin</Badge>
        </Navbar.Brand>
        <Navbar.Toggle />
        <Navbar.Collapse className="justify-content-end gap-3">
          <div className="d-flex align-items-center gap-2">
            <div 
              className="d-flex align-items-center justify-content-center text-white fw-bold shadow-sm"
              style={{
                width: '36px',
                height: '36px',
                borderRadius: '50%',
                background: 'linear-gradient(135deg, #05cd99 0%, #11e4a7 100%)',
                fontSize: '14px'
              }}
            >
              {user?.name ? user.name.charAt(0).toUpperCase() : 'A'}
            </div>
            <div>
              <div className="fw-semibold small leading-none">{user?.name || 'Central Admin'}</div>
              <div className="text-muted" style={{ fontSize: '11px' }}>{user?.email}</div>
            </div>
          </div>

          <div className="vr d-none d-lg-block mx-1"></div>

          <Button 
            variant="outline-secondary" 
            size="sm" 
            className="d-flex align-items-center gap-1"
            onClick={toggleTheme}
            style={{ borderRadius: '10px' }}
          >
            🌓 Theme
          </Button>
          <Button 
            variant="outline-danger" 
            size="sm" 
            onClick={logout}
            style={{ borderRadius: '10px' }}
          >
            Logout ➔
          </Button>
        </Navbar.Collapse>
      </Navbar>

      {/* Main Layout */}
      <Container fluid className="flex-grow-1 p-0">
        <Row className="g-0 min-vh-100">
          {/* Sidebar */}
          <Col lg={2} md={3} className="p-3 border-end bg-body">
            <div className="small text-uppercase fw-bold text-muted mb-3 px-3" style={{ letterSpacing: '1px' }}>
              Admin Controls
            </div>
            <nav className="d-flex flex-column gap-1">
              <NavLink to="/admin/staff" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}><FaUsers className="me-2"/> Staff Management</NavLink>
              <NavLink to="/admin/analytics" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}><FaChartBar className="me-2"/> Real-Time Analytics</NavLink>
              <NavLink to="/admin/activity" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}><FaListAlt className="me-2"/> Activity Logs</NavLink>
              <NavLink to="/admin/settings" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}><FaCog className="me-2"/> System Settings</NavLink>
            </nav>
          </Col>

          {/* Dynamic Content */}
          <Col lg={10} md={9} className="p-4" style={{ background: 'var(--bg-primary)' }}>
            <AdminRoutes />
          </Col>
        </Row>
      </Container>
    </div>
  );
};

export default AdminDashboard;
